import { Extension, OverviewPanel, Product } from "@nucleum/client/config/product.type";
import { getProductNavConfig } from "@nucleum/client/config/product-nav.config";
import { Resource } from "@nucleum/datafn/resource.enum";
import { Action } from "@nucleum/client/config/action.enum";
import { MemotronAction } from "@nucleum/features/memory/memory-action.enum";
import type { ISelectItem } from "@21n/ui/elements/select/select.type";
import {
  nextProducts,
  nextResourceTableMap,
  nextNucleusOverviewPanelSwitcherItems
} from "@nucleum/next/product.config";
import {
  resolveProductResourceConfig,
  sharedExtensions,
  productRegistry
} from "@nucleum/schema/product.config";
import type { IProductConfigBase as ISharedProductConfigBase } from "@nucleum/schema/product.config";

const isDev = import.meta.env?.DEV || false;

interface SettingsSection {
  children: (Action | MemotronAction | string)[];
  isHideTitle?: boolean;
  orientation?: "horizontal" | "vertical";
  section: string;
}

type IProductConfigBase = ISharedProductConfigBase;

export interface IAppConfigBase extends IProductConfigBase {
  /**
   * @deprecated
   */
  version?: string;
  /**
   * @deprecated
   */
  build?: number;
  /**
   * App menu for landscape mode
   */
  appMenu: string[];
  /**
   * App menu for portrait mode
   */
  appMenuPt: string[];
  /**
   * Home path for landscape mode
   */
  homePath: string;
  /**
   * Home path for portrait mode
   */
  homePathPt: string;
  isShowCaptureOnMobile?: boolean;
  settings?: SettingsSection[];
  databaseName?: string;
  librarySectionLabel?: string;
  configurableShortcuts?: string[];
  oAuthProviders?: ("google" | "apple" | "github")[];
  overviewPanelSwitcherItems?: ISelectItem[];
}

type IAppConfig = IAppConfigBase;

type IExtensionConfig = IProductConfigBase;

const commonConfigurableShortcuts = [
  Action.EDIT_MODE,
  Action.CMD,
  Action.SEARCH,
  Action.GO_BACK,
  Action.GO_FORWARD
];

const nucleusNav = getProductNavConfig(Product.NUCLEUM);
const memotronNav = getProductNavConfig(Product.MEMOTRON);
const pointronNav = getProductNavConfig(Product.POINTRON);

const resolveBaseSharedProductConfig = (productName: Product) =>
  productRegistry[productName.toString() as keyof typeof productRegistry];

const uniqueResources = (resources: Resource[]) =>
  Array.from(new Set(resources));

const resolveClientProductResources = (productName: Product) => {
  const sharedResources = resolveProductResourceConfig(productName, { isDev });
  const nextTables =
    productName === Product.NUCLEUM
      ? Array.from(Object.values(nextResourceTableMap)).flat()
      : (nextResourceTableMap[
          productName as keyof typeof nextResourceTableMap
        ] ?? []);
  return {
    browse: sharedResources.browse as Resource[],
    table: uniqueResources([
      ...(sharedResources.table as Resource[]),
      ...(nextTables as Resource[])
    ])
  };
};

export const products: Record<string, IAppConfigBase> = {
  [Product.NUCLEUM]: {
    ...resolveBaseSharedProductConfig(Product.NUCLEUM),
    appMenu: (isDev && nucleusNav.appMenuDev
      ? nucleusNav.appMenuDev
      : nucleusNav.appMenu) as string[],
    appMenuPt: [...nucleusNav.appMenuPt],
    homePath: nucleusNav.homePath,
    homePathPt: nucleusNav.homePathPt,
    resources: resolveClientProductResources(Product.NUCLEUM),
    librarySectionLabel: nucleusNav.librarySectionLabel,
    configurableShortcuts: [
      ...commonConfigurableShortcuts,
      "SAVE_CAPTURE_SHORTCUT",
      "ACTIVATE_LINK_BOX"
    ],
    overviewPanelSwitcherItems: [
      { label: "Dashboard", value: OverviewPanel.DASHBOARD, icon: "overview" },
      { label: "Graph", value: OverviewPanel.GRAPH, icon: "graph" },
      ...nextNucleusOverviewPanelSwitcherItems
    ],
    settings: [
      {
        children: [
          Action.SYNC_SETTINGS,
          Action.ARTIFICIAL_INTELLIGENCE,
          Action.DATA_SETTINGS,
          Action.USER_BILLING
        ],
        isHideTitle: true,
        orientation: "horizontal",
        section: "app"
      },
      {
        children: [
          Action.MODE_OF_INTERACTION,
          Action.APPEARANCE_SETTINGS,
          "analytics-settings",
          "session-settings",
          MemotronAction.NODE_SETTINGS,
          Action.DATETIME_SETTINGS,
          Action.SHORTCUTS,
          Action.ACCESSIBILITY
        ],
        section: "customization"
      },
      {
        children: [
          "about",
          "green",
          "share",
          "guides",
          "feedback",
          "privacy",
          "discord"
        ],
        isHideTitle: true,
        section: "other"
      }
    ]
  },
  [Product.MEMOTRON]: {
    ...resolveBaseSharedProductConfig(Product.MEMOTRON),
    appMenu: [...memotronNav.appMenu],
    appMenuPt: [...memotronNav.appMenuPt],
    homePath: memotronNav.homePath,
    homePathPt: memotronNav.homePathPt,
    isShowCaptureOnMobile: true,
    resources: resolveClientProductResources(Product.MEMOTRON),
    librarySectionLabel: memotronNav.librarySectionLabel,
    configurableShortcuts: [
      ...commonConfigurableShortcuts,
      "SAVE_CAPTURE_SHORTCUT",
      "ACTIVATE_LINK_BOX"
    ],
    settings: [
      {
        children: [
          MemotronAction.RELATIONS_AS_SETTINGS,
          Action.SYNC_SETTINGS,
          Action.ARTIFICIAL_INTELLIGENCE,
          Action.DATA_SETTINGS,
          Action.USER_BILLING
        ],
        isHideTitle: true,
        orientation: "horizontal",
        section: "app"
      },
      {
        children: [
          Action.MODE_OF_INTERACTION,
          Action.APPEARANCE_SETTINGS,
          MemotronAction.NODE_SETTINGS,
          Action.DATETIME_SETTINGS,
          Action.SHORTCUTS,
          Action.ACCESSIBILITY
        ],
        section: "customization"
      },
      {
        children: [
          "about",
          "green",
          "share",
          "guides",
          "feedback",
          "privacy",
          "discord"
        ],
        isHideTitle: true,
        section: "other"
      }
    ]
  },
  [Product.POINTRON]: {
    ...resolveBaseSharedProductConfig(Product.POINTRON),
    appMenu: [...pointronNav.appMenu],
    appMenuPt: [...pointronNav.appMenuPt],
    homePath: pointronNav.homePath,
    homePathPt: pointronNav.homePathPt,
    resources: resolveClientProductResources(Product.POINTRON),
    librarySectionLabel: pointronNav.librarySectionLabel,
    settings: [
      {
        children: [
          Action.SYNC_SETTINGS,
          Action.DATA_SETTINGS,
          Action.USER_BILLING
        ],
        isHideTitle: true,
        orientation: "horizontal",
        section: "app"
      },
      {
        children: [
          Action.MODE_OF_INTERACTION,
          Action.APPEARANCE_SETTINGS,
          "analytics-settings",
          "session-settings",
          Action.DATETIME_SETTINGS,
          Action.SHORTCUTS,
          Action.ACCESSIBILITY
        ],
        section: "customization"
      },
      {
        children: [
          "about",
          "green",
          "share",
          "guides",
          "feedback",
          "privacy",
          "discord"
        ],
        isHideTitle: true,
        section: "other"
      }
    ]
  },
  ...nextProducts
};

export const product =
  import.meta.env?.VITE_PRODUCT ||
  (typeof process !== "undefined"
    ? process.env?.PLASMO_PUBLIC_PRODUCT
    : undefined) ||
  Product.NUCLEUM;

export const resolveProductConfig = (productOverride?: Product): IAppConfig => {
  const base = products[productOverride ?? (product as Product)];
  if (!base) {
    throw new Error(`Unknown product: ${productOverride ?? product}`);
  }
  return {
    ...base,
    oAuthProviders: ["google", "apple", "github"]
  };
};

const extensions: Record<Extension, IProductConfigBase> = {
  [Extension.MEMOTRON_CLIPPER]: {
    name: "Memotron Clipper",
    resources: {
      browse: [],
      table: sharedExtensions[Extension.MEMOTRON_CLIPPER].resources
        .table as Resource[]
    },
    displayName: "Memotron Clipper",
    tagline: ""
  },
  [Extension.MEMOTRON_SHARE]: {
    name: "Memotron Share",
    resources: {
      browse: [],
      table: []
    },
    displayName: "Memotron Share",
    tagline: ""
  }
};

export const resolveExtensionConfig = (
  productOverride?: Extension
): IExtensionConfig => {
  const base = extensions[productOverride ?? (product as Extension)];
  return base;
};
/**
 * Product-wide navigation chrome configuration shared with the application
 * shell. The composition root installs the full product config; the shell only
 * reads the narrow navigation fields it needs, keeping product assembly in
 * `client/products`.
 */
export type ProductNavConfig = {
  appMenu: string[];
  appMenuPt: string[];
  homePath: string;
  homePathPt: string;
  isShowCaptureOnMobile?: boolean;
};

let productConfig: ProductNavConfig | undefined;

/**
 * Installs the resolved product navigation config from `resource-hosts.ts`.
 */
export function configureProductConfigHost(value: ProductNavConfig) {
  productConfig = value;
}

/**
 * Reads the installed product navigation config. Throws when the composition
 * root has not configured the host.
 */
export function requireProductConfig(): ProductNavConfig {
  if (!productConfig)
    throw new Error("Product config host has not been configured");
  return productConfig;
}
import type { Component } from "svelte";

export interface ElementActionHost {
  openLink(href: string): void;
  renderer: Component<{ path?: string; params?: any }>;
  runAction(action: string, params?: any): any;
}

let host: ElementActionHost | undefined;

/** Installs application actions used by portable interactive elements. */
export function configureElementActionHost(value: ElementActionHost) {
  host = value;
}

/** Returns the optional action host supplied by the composing application. */
export function getElementActionHost() {
  return host;
}
import type { Component } from "svelte";

export interface ElementFile {
  id?: string;
  thumbnailUrl?: string | null;
  url?: string | null;
}

export interface ElementFileHost {
  renderer?: Component<{ id?: string; class?: string }>;
  resolve(
    file: string | ElementFile,
    options?: { isUseThumbnailIfAvailable?: boolean }
  ): Promise<ElementFile | undefined>;
}

let host: ElementFileHost | undefined;

/** Installs file resolution for portable media presentation. */
export function configureElementFileHost(value: ElementFileHost) {
  host = value;
}

/** Returns the optional file host supplied by the composing application. */
export function getElementFileHost() {
  return host;
}

/** Resolves file presentation data through the optional application host. */
export function resolveElementFile(
  file: string | ElementFile,
  options?: { isUseThumbnailIfAvailable?: boolean }
) {
  return getElementFileHost()?.resolve(file, options);
}
export interface ElementSearchHost {
  onSelected(item: Record<string, unknown>): void;
}

let host: ElementSearchHost | undefined;

/** Installs application reactions to portable search selection. */
export function configureElementSearchHost(value: ElementSearchHost) {
  host = value;
}

/** Notifies the optional application host of a search selection. */
export function notifyElementSearchSelection(item: Record<string, unknown>) {
  host?.onSelected(item);
}
import type { IKeyboardShortcut } from "@21n/ui/elements/keyboard/shortcut.type";
import { writable } from "svelte/store";

export interface ElementShortcutHost {
  resolve(action: string): IKeyboardShortcut | undefined;
}

let host: ElementShortcutHost | undefined;

/** Reactive shortcut presentation state supplied by the application. */
export const elementShortcutState = writable({
  isShowHints: true,
  revision: 0
});

/** Installs shortcut resolution without exposing persistence to elements. */
export function configureElementShortcutHost(value: ElementShortcutHost) {
  host = value;
}

/** Marks shortcut resolution data as changed. */
export function notifyElementShortcutsChanged() {
  elementShortcutState.update((state) => ({
    ...state,
    revision: state.revision + 1
  }));
}

/** Updates whether portable controls should display shortcut hints. */
export function syncElementShortcutHints(isShowHints: boolean) {
  elementShortcutState.update((state) => ({ ...state, isShowHints }));
}

/** Resolves a configured shortcut for presentation. */
export function resolveElementShortcut(action: string) {
  return host?.resolve(action);
}
import colorSchemes from "@21n/theme/colorschemes.json";
import type { ColorScheme } from "@21n/theme/appearance.type";
import { writable } from "svelte/store";

export interface ElementPlatform {
  embed: string;
  experiments?: Record<string, unknown>;
  isEmbed: boolean;
  isTouchDevice: boolean;
  os: string;
}

export interface ElementAppearance {
  colorScheme: ColorScheme;
}

export interface ElementLogger {
  debug(message: unknown): void;
  error(message: unknown, error?: unknown): void;
  info(message: unknown): void;
  log(message: unknown): void;
  warn(message: unknown): void;
}

const defaultColorScheme = colorSchemes[0] as ColorScheme;

/** Platform presentation state supplied by the host application. */
export const elementPlatform = writable<ElementPlatform>({
  embed: "NONE",
  isEmbed: false,
  isTouchDevice: false,
  os: "UNDETERMINED"
});

/** Theme presentation state supplied by the host application. */
export const elementAppearance = writable<ElementAppearance>({
  colorScheme: defaultColorScheme
});

/** Development presentation state supplied by the host application. */
export const elementDebugMode = writable(false);

let logger: ElementLogger = {
  debug: () => {},
  error: () => {},
  info: () => {},
  log: () => {},
  warn: () => {}
};
let haptic: () => void = () => {};
let assetPathResolver = (path: string) => path;

/** Logger facade configured by an application host. */
export const elementLogger: ElementLogger = {
  debug: (message) => logger.debug(message),
  error: (message, error) => logger.error(message, error),
  info: (message) => logger.info(message),
  log: (message) => logger.log(message),
  warn: (message) => logger.warn(message)
