const olds=oldPaths.filter(f=>/\.(ts|svelte|mjs|json)$/.test(f)&&!f.includes('lock'));
const raw=cp.spawnSync('git',['cat-file','--batch'],{input:olds.map(f=>'HEAD:'+f).join('\n')+'\n',maxBuffer:100*1024*1024}).stdout;
