<script lang="ts">
  import Button from "@21n/ui/elements/button/Button.svelte";
  import TextInput from "@21n/ui/elements/input/TextInput.svelte";
  import { isValidEmail } from "@21n/shared-utils/text.utils";
  import { stringify } from "@21n/shared-utils/json.utils";

  let { product }: { product: any } = $props();
  let emailEntered = "";
  let errorMessage: string | undefined = undefined;
  let successMessage: string | undefined = undefined;
  let previousEmailEntered = "";
  const subscriptionUrl =
    "https://3yin6uycm6.execute-api.us-east-1.amazonaws.com/prod/utils/communication";
  $effect(() => {
    if (emailEntered === previousEmailEntered) return;
    previousEmailEntered = emailEntered;
    errorMessage = undefined;
  });
  async function handleSubmit() {
    if (!isValidEmail(emailEntered)) {
      successMessage = undefined;
      errorMessage = "Please enter valid email address";
      return;
    }
    let response = await fetch(subscriptionUrl, {
      method: "POST",
      body: stringify({
        email: emailEntered,
        product
      })
    });
    let responseBody = await response.json();
    if (responseBody && responseBody.code == 1) {
      errorMessage = undefined;
      successMessage = responseBody.message;
      setTimeout(() => {
        emailEntered = "";
      }, 2000);
    } else {
      successMessage = undefined;
      errorMessage = responseBody.message;
    }
    clearMessages();
  }
  function clearMessages() {
    setTimeout(() => {
      successMessage = undefined;
      errorMessage = undefined;
    }, 3000);
  }
</script>

<div class="flex flex-col gap-2 items-center justify-center">
  <div class="flex items-center justify-center flex-wrap gap-4">
    <TextInput
      placeholder="enter your email"
      bind:value={emailEntered}
    />
    <Button label="Get early access" type="primary" onclick={handleSubmit} />
  </div>
  <div class="h-6">
    {#if errorMessage}
      <div class="text-ars1">{errorMessage}</div>
    {/if}
    {#if successMessage}
      <div class="text-ags1">{successMessage}</div>
    {/if}
  </div>
</div>
<script lang="ts">
  import Button from "@21n/ui/elements/button/Button.svelte";
  import TextInput from "@21n/ui/elements/input/TextInput.svelte";
  import CopyableText from "@21n/ui/elements/text/CopyableText.svelte";
  import OptionSelector from "@21n/ui/elements/select/OptionSelector.svelte";
  import { Size } from "@21n/ui/elements/size.enum";
  import { ButtonVariant } from "@21n/ui/elements/button/button.type";
  import { InputStyle } from "@21n/ui/elements/input/input.type";
  import {
    OptionSelectorStyle,
    type ISelectValue
  } from "@21n/ui/elements/select/select.type";
  import { toasts } from "@nucleum/shared-state/notifications/notification.store";
  import {
    createDatafnPublicLink,
    getDatafnPermissions,
    resolveDatafnUserPrincipal,
    resolveDatafnPublicLinkUrl,
    revokeDatafnPublicLink,
    shareDatafnRecord,
    shareDatafnResourceScope,
    unshareDatafnRecord,
    unshareDatafnResourceScope,
    type DatafnPermissionGrant,
    type DatafnShareLevel,
    type DatafnShareScope
  } from "@nucleum/datafn/datafn-sharing.store";
  import account from "@nucleum/client/runtime/account/account.store";
  import { get } from "svelte/store";

  let {
    resource,
    id
  }: {
    resource: string;
    id: string;
  } = $props();

  let principalInput = $state("");
  let level = $state<ISelectValue>("viewer");
  let scope = $state<ISelectValue>("record");
  let permissions = $state<DatafnPermissionGrant[]>([]);
  let publicLinkUrl = $state("");
  let isLoading = $state(false);
  let isPublicLinkLoading = $state(false);
  let errorMessage = $state("");

  const levelOptions = [
    { label: "View", value: "viewer" },
    { label: "Edit", value: "editor" },
    { label: "Own", value: "owner" }
  ];
  const scopeOptions = [
    { label: "Record", value: "record" },
    { label: "Resource", value: "resource" }
  ];
  const selectedLevel = $derived(level as DatafnShareLevel);
  const selectedScope = $derived(scope as DatafnShareScope);
  const isRecordScope = $derived(selectedScope === "record");
  const canUseSharing = $derived(Boolean(id));

  $effect(() => {
    void loadPermissions();
  });

  async function loadPermissions() {
    if (!id) {
      permissions = [];
      errorMessage = "Open sharing from a specific record.";
      return;
    }
    try {
      permissions = await getDatafnPermissions({ resource, id });
    } catch (error) {
      errorMessage = resolveErrorMessage(error);
    }
  }

  async function shareWithUser() {
    if (!canUseSharing) return;
    isLoading = true;
    errorMessage = "";
    try {
      const principalId = resolveDatafnUserPrincipal(principalInput);
      permissions = isRecordScope
        ? await shareDatafnRecord({
            resource,
            id,
            principalId,
            level: selectedLevel
          })
        : await shareDatafnResourceScope({
            resource,
            principalId,
            level: selectedLevel,
            permissionsRecordId: id
          });
      principalInput = "";
      toasts.success("Permission updated");
    } catch (error) {
      errorMessage = resolveErrorMessage(error);
      toasts.error(errorMessage);
    } finally {
      isLoading = false;
    }
  }

  async function createPublicLink() {
    if (!canUseSharing) return;
    isPublicLinkLoading = true;
    errorMessage = "";
    try {
      const link = await createDatafnPublicLink({
        resource,
        recordId: isRecordScope ? id : null,
        scope: selectedScope,
        level: selectedLevel
      });
      publicLinkUrl = resolveDatafnPublicLinkUrl({
        token: link.token,
        resource,
        recordId: id,
        region: get(account).userInfo?.region ?? "insouth"
      });
      permissions = await getDatafnPermissions({ resource, id });
      toasts.success("Public link created");
    } catch (error) {
      errorMessage = resolveErrorMessage(error);
      toasts.error(errorMessage);
    } finally {
      isPublicLinkLoading = false;
    }
  }

  async function revokePermission(permission: DatafnPermissionGrant) {
    if (!canUseSharing) return;
    isLoading = true;
    errorMessage = "";
    try {
      if (permission.principalId.startsWith("public_link:")) {
        await revokeDatafnPublicLink({
          id: permission.principalId.slice("public_link:".length)
        });
      }
      permissions =
        permission.grantKind === "resource"
          ? await unshareDatafnResourceScope({
              resource,
              principalId: permission.principalId,
              permissionsRecordId: id
            })
          : id
            ? await unshareDatafnRecord({
                resource,
                id,
                principalId: permission.principalId
              })
            : permissions;
      toasts.success("Permission revoked");
    } catch (error) {
      errorMessage = resolveErrorMessage(error);
      toasts.error(errorMessage);
    } finally {
      isLoading = false;
    }
  }

  function resolveErrorMessage(error: unknown) {
    if (error && typeof error === "object" && "message" in error) {
      const message = (error as { message?: unknown }).message;
      if (typeof message === "string") return message;
    }
    return "Sharing failed";
  }
</script>

<div class="flex flex-col gap-5 p-6 min-w-[26rem] max-w-[36rem]">
  <div class="flex flex-col gap-3">
    <div class="grid grid-cols-2 gap-3">
      <OptionSelector
        bind:selected={level}
        options={levelOptions}
        size={Size.sm}
        style={OptionSelectorStyle.TRAIN}
      />
      <OptionSelector
        bind:selected={scope}
        options={scopeOptions}
        size={Size.sm}
        style={OptionSelectorStyle.TRAIN}
      />
    </div>
    <div class="flex flex-row gap-2 items-center">
      <TextInput
        bind:value={principalInput}
        placeholder="user id or email"
        style={InputStyle.BORDERED}
        size={Size.sm}
        isDisabled={isLoading}
      />
      <Button
        label="Share"
        icon="share"
        size={Size.sm}
        variant={ButtonVariant.PRIMARY}
        {isLoading}
        isDisabled={!principalInput.trim() || !canUseSharing}
        onclick={shareWithUser}
      />
    </div>
    <Button
      label="Create public link"
      icon="link"
      size={Size.sm}
      isLoading={isPublicLinkLoading}
      isDisabled={!canUseSharing}
      onclick={createPublicLink}
    />
  </div>

  {#if publicLinkUrl}
    <CopyableText parentBackgroundIndex={1} text={publicLinkUrl} />
  {/if}

  {#if errorMessage}
    <p class="text-b3 text-ars1">{errorMessage}</p>
  {/if}

  <div class="flex flex-col gap-2">
    {#each permissions as permission}
      <div
        class="flex flex-row items-center justify-between gap-3 border border-brs2 rounded-md px-3 py-2"
      >
        <div class="flex flex-col min-w-0">
          <span class="text-b3 truncate">{permission.principalId}</span>
          <span class="text-b4 text-fgs2"
            >{permission.level} / {permission.grantKind}</span
          >
        </div>
        <Button
          icon="trash"
          tooltip="Revoke"
          size={Size.sm}
          variant={ButtonVariant.DANGER}
          {isLoading}
          onclick={() => revokePermission(permission)}
        />
      </div>
    {:else}
      <p class="text-b3 text-fgs2">No shared permissions yet</p>
    {/each}
  </div>
</div>
export interface IQuickAccessItem {
  id: string;
  label: string;
  icon: string;
  count?: number;
}
<script lang="ts">
  import Icon from "@21n/ui/elements/Icon.svelte";
  import { Size } from "@21n/ui/elements/size.enum";
  import Badge from "@21n/ui/elements/text/Badge.svelte";
  import type { IQuickAccessItem } from "@nucleum/application/home/home.type";
  let {
    items = [],
    onItemClick = undefined
  }: {
    items?: IQuickAccessItem[];
    onItemClick?: ((item: IQuickAccessItem) => void) | undefined;
  } = $props();

  function handleItemClick(item: IQuickAccessItem) {
    onItemClick?.(item);
  }

  function formatCount(count: number): string {
    if (count >= 1000) {
      return (count / 1000).toFixed(1) + "k";
    }
    return count.toString();
  }
</script>

<div class="px-4 py-2">
  <div class="grid grid-cols-2 gap-2">
    {#each items as item}
      <button
        class="flex items-center justify-between gap-2 px-2 bg-bgs1 hover:bg-bgs3 rounded-lg transition-colors h-11"
        onclick={() => handleItemClick(item)}
      >
        <div class="flex items-center gap-1">
          <Icon icon={item.icon} size={Size.sm} class="text-fgs2" />
          <div class="flex items-center gap-1.5">
            <span class="text-fgs1 text-b2">{item.label}</span>
            {#if item.count !== undefined}
              <Badge text={formatCount(item.count)} />
            {/if}
          </div>
        </div>
        <Icon icon="chevron-right" size={Size.sm} class="text-fgs2" />
      </button>
    {/each}
  </div>
</div>

