    const order: string[] = [];
    mocks.verifyPayment.mockImplementation(async () => {
      order.push("verify");
      return { status: "success" };
    });
    const handled = await handleNativePurchase(
      { type: "PURCHASE_SUCCESS", nonce: "nonce", embedTransaction: "transaction" },
