import { performApiCall } from "@21n/utils/network.utils";

/** Exchanges a legacy OAuth callback code using the browser session verifier. */
export async function handleOAuthRedirection(
  slug: string,
  code: string | null
) {
  if (!slug || !code) return;
  const app = import.meta.env?.VITE_HOST ?? window.location.hostname;
  const verifier = sessionStorage.getItem("verifier");
  const body = {
    slug,
    code,
    verifier,
    app
  };
  let response = await performApiCall("account/n/oauth", "POST", body);
  console.log(response);
  if (response) {
    if (response.status === 200) {
      return response;
    }
  }
  return null;
}
import { appStore } from "@nucleum/shared-state/app-context/app.store";

import { ClientStorageKey } from "@nucleum/persistence/persistence.type";
import { clientStorage } from "@nucleum/persistence/persistence.utils";

import { parse } from "@21n/shared-utils/json.utils";

/** Loads the newest cached or bundled metadata, applying the composing product identity. */
export async function loadInitialProductData(
  dynamicProductData: any,
  details: { name: string; version: string; build: number }
) {
  const cachedAppData = await clientStorage.get(ClientStorageKey.APP_DATA);
  const cachedAppDataJson = parse(cachedAppData ?? "{}");

  let data =
    cachedAppDataJson &&
    cachedAppDataJson?.dataVersion >= dynamicProductData?.dataVersion
      ? {
          ...cachedAppDataJson
        }
      : {
          ...dynamicProductData
        };
  data = {
    ...data,
    name: details.name,
    version: details.version,
    build: details.build
  };
  appStore.loadAppData(data, {
    isDefaultData: true
  });
}
import { get } from "svelte/store";

import { userPreferences } from "@nucleum/shared-state/preferences/user-preferences.store";

import { logger } from "@nucleum/client/runtime/logging/logger";

import { detectTimeZone } from "@21n/utils/time.utils";

import { nucleumDatafnStatus } from "@nucleum/datafn/datafn.store";

/** Persists a detected timezone change using the preference store. */
export async function refreshTimeZone() {
  if (get(nucleumDatafnStatus).nucleumMode === null) return;
  const timeZone = detectTimeZone();
  if (!timeZone || !get(userPreferences)) return;
  const offset = timeZone.offset * 60;
  if (
    get(userPreferences).timeZoneOffset === offset &&
    get(userPreferences).timeZone === timeZone.zone
  ) {
    return;
  }
  logger.info({
    at: "refreshTimeZone - timezone change detected",
    timeZone
  });
  await userPreferences.setTimeZone(offset, timeZone.label, timeZone.zone);
}
