  import { navigation } from "@nucleum/shell/navigation/navigation";
  import { accountDeletion } from "@nucleum/surfaces/account/account-deletion";

  import Button from "@21n/ui/elements/button/Button.svelte";
  import account from "@nucleum/client/runtime/account/account.store";
  import { accountSession } from "@nucleum/surfaces/account/account-session";
  import { appStore } from "@nucleum/shared-state/app-context/app.store";
  import { ButtonStyle, ButtonVariant } from "@21n/ui/elements/button/button.type";
  import { properCase } from "@21n/shared-utils/text.utils";
  import RegionSetting from "@nucleum/surfaces/settings/account/RegionSetting.svelte";
  import InlineInfoBanner from "@21n/ui/elements/text/InlineInfoBanner.svelte";
  import InlineErrorMessage from "@21n/ui/elements/text/InlineErrorMessage.svelte";
  import { InfoTextType } from "@21n/ui/elements/text/info.type";

  let region = $state("useast");
  let isBootstrapInProgress = $state(false);
  let error = $state<string | null>(null);

  const productName = $derived(properCase($appStore?.product ?? "nucleum"));
  const currentUserInfo = $derived($account?.userInfo);
  const isAlreadyBootstrapped = $derived(
    Boolean(currentUserInfo?.isBootstrapped && currentUserInfo?.region)
  );

  $effect(() => {
    if (currentUserInfo?.region) {
      region = currentUserInfo.region;
    }
  });
</script>

