    return data;
  }

  async triggerUnsplashDownload(params?: { url: string }) {
    const response = resolveJsonResponse(
      await performApiCall("utils/n/run", "POST", {
        action: "unsplash-download",
        ...params
      })
    );

    if (!response?.ok) return;
    const data = await response.json();
    return data;
  }
}

