  if (userInfo) {
    seed.userInfo = userInfo;
    seed.userId = userInfo.id.split("user:")[1];
    seed.plan = storedPlan;
    seed.dataMode = UserDataMode.CLOUD;
    seed.sessionType = UserSessionType.RETURNING;
  }
  account.set(seed);
  postToEmbed(seed);
}

