class FeedbackPaneStore extends ObservableStore<IFeedbackPaneStore> {
  constructor() {
    super("feedbackPane");
    this.set({
      isShown: false,
      feedback: "",
      focusedClip: null,
      modalClip: null
    });
  }
  reset() {
    this.update(() => {
      return {
        isShown: false,
        feedback: "",
        focusedClip: null,
        modalClip: null
      };
    });
  }
  toggle(params?: { isUserInitiated?: boolean }) {
    this.update((n) => {
      n.isShown = !n.isShown;
      n.isUserInitiated = params?.isUserInitiated ?? false;
      return n;
    });
  }
  focus(
    clip: IClip | null,
    message: string | { message: string; type: AlertType }
  ) {
    logger.log({ at: "feedbackPane.focus", clip, message });
    this.update((n) => {
      n.focusedClip = clip;
      n.feedback = message;
      n.isShown = true;
      return n;
    });
  }
  openInModal(clip: IClip | null) {
    this.update((n) => {
      n.modalClip = clip;
      return n;
    });
  }
  closeModalClip() {
    this.update((n) => {
      n.modalClip = null;
      return n;
    });
  }
  /**
