    this.modify({ isOpen });
    if (isOpen) {
      setTimeout(() => {
        webpage.refresh();
      }, 100);
    }
  },

  toggleVisibility(isHidden?: boolean) {
    if (isHidden === undefined) {
      isHidden = !this.get().isHidden;
