function isDatafnE2eeSettings(
  value: unknown
): value is NucleumDatafnE2eeSettings {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    (value as { version?: unknown }).version === 1 &&
    typeof (value as { enabled?: unknown }).enabled === "boolean"
  );
