  subType?: NodeType | CollectionType;
}) {
  const targetResource =
    signalResource ??
    (resource === Resource.relation ? Resource.linkTag : resource);
  const filters =
    targetResource === Resource.node
      ? {
          ...(params.filters ?? {}),
          contentType: params.subType
            ? params.subType
            : { $in: [...rootNodeTypeList] },
          metaType: { $is_empty: true },
