const root = '/Users/serro/Documents/dev/n/nucleus/';
const parse = file => ts.createSourceFile(file, fs.readFileSync(file, 'utf8'), ts.ScriptTarget.Latest, true);
const declaration = (sf, name) => sf.statements.filter(ts.isVariableStatement).flatMap(s => [...s.declarationList.declarations]).find(d => d.name.getText(sf) === name);
const old = parse('/tmp/nucleus-organization.GYqU7M/before/client/surfaces/commandBar/actionMap.ts');
const current = parse(root + 'client/application/composition/global-commands.ts');
const modules = new Map();
for (const imp of current.statements.filter(ts.isImportDeclaration)) {
  const alias = imp.moduleSpecifier.text;
  const file = alias.replace('@nucleum/', 'client/') + '.ts';
  if (!fs.existsSync(root + file)) continue;
  const sf = parse(root + file);
  for (const binding of imp.importClause?.namedBindings?.elements ?? []) {
    const decl = declaration(sf, binding.name.text);
    if (!decl) continue;
    const obj = ts.isSatisfiesExpression(decl.initializer) ? decl.initializer.expression : decl.initializer;
    modules.set(binding.name.text, { sf, obj });
  }
}
const tokens = text => {
  const scanner = ts.createScanner(ts.ScriptTarget.Latest, true, ts.LanguageVariant.Standard, text);
  const result = [];
  for (let token = scanner.scan(); token !== ts.SyntaxKind.EndOfFileToken; token = scanner.scan()) {
    if (token !== ts.SyntaxKind.CommaToken) result.push(scanner.getTokenText());
  }
  return result.join(' ');
};
