  const expression = ts.isSpreadElement(assembled[i]) ? assembled[i].expression : assembled[i];
  const name = expression.expression.getText(current);
  const key = ts.isElementAccessExpression(expression) ? expression.argumentExpression.getText(current) : expression.name.text;
  const { sf, obj } = modules.get(name);
  const prop = obj.properties.find(p => p.name.getText(sf) === key);
  const before = ts.isSpreadElement(original[i]) ? original[i].expression : original[i];
  if (tokens(before.getText(old)) !== tokens(prop.initializer.getText(sf))) throw Error('Command differs at ' + i + ': ' + name + '.' + key);
}
