        at: "FallbackTracker.runIfNotCompleted",
        fallbackName,
        message: "Completed successfully"
      });
      return 1;
    } catch (error) {
      logger.error({
        at: "FallbackTracker.runIfNotCompleted",
        fallbackName,
        error,
        message: "Failed to run fallback"
      });
      throw error;
    }
  }
}
import { setContext, getContext } from "svelte";
import { writable, type Writable } from "svelte/store";

type EventCallback = (detail: any) => void;
type EventListeners = Record<string, EventCallback[]>;

interface EventContext {
  addEventListener: (eventName: string, callback: EventCallback) => void;
  removeEventListener: (eventName: string, callback: EventCallback) => void;
  dispatchEvent: (eventName: string, detail: any) => void;
}

/** Creates a context-scoped event dispatcher shared by reusable controls. */
export function createEventPropagator(
  uniqueKey: string = "defaultEventPropagator"
) {
  const eventListeners: Writable<EventListeners> = writable({});

  const eventContext: EventContext = {
    addEventListener: (eventName: string, callback: EventCallback) => {
      eventListeners.update((listeners) => {
        if (!listeners[eventName]) {
          listeners[eventName] = [];
        }
        listeners[eventName].push(callback);
        return listeners;
      });
    },
    removeEventListener: (eventName: string, callback: EventCallback) => {
      eventListeners.update((listeners) => {
        if (listeners[eventName]) {
          listeners[eventName] = listeners[eventName].filter(
            (cb) => cb !== callback
          );
        }
        return listeners;
      });
    },
    dispatchEvent: (eventName: string, detail: any) => {
      eventListeners.update((listeners) => {
        if (listeners[eventName]) {
          listeners[eventName].forEach((callback) => callback(detail));
        }
        return listeners;
      });
    }
  };

  return {
    setEventContext: () => setContext<EventContext>(uniqueKey, eventContext),
    getEventContext: () => getContext<EventContext>(uniqueKey)
  };
}
export function cleanText(text: string): string {
  return text
    .replace(/\(resource=[a-zA-Z]+:[a-zA-Z0-9_-]+\)/g, "")
    .replace(/\bresource:[a-zA-Z0-9_-]+\b/g, "")
    .replace(/https?:\/\/[^\s)]+/g, "")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^===+$/gm, "")
    .replace(/[​\u200B-\u200D\uFEFF]/g, "")
    .trim();
}

export function extractSearchFields(
  record: any,
  searchIndices: string[]
): Record<string, string> | undefined {
  try {
    const fields: Record<string, string> = {};
    let hasContent = false;

    for (const fieldName of searchIndices) {
      let value = record[fieldName];
      if (Array.isArray(value))
        value = value.filter((v) => v != null).join(" ");
      if (value && typeof value === "object") continue;
      if (value != null && value !== "") {
        const cleanedValue = cleanText(String(value));
        if (cleanedValue?.length > 0) {
          fields[fieldName] = cleanedValue;
          hasContent = true;
        }
      }
    }

    return hasContent ? fields : undefined;
  } catch (e) {
    console.error("Error extracting search fields:", e);
    return undefined;
  }
}
