import type { ClipperExtensionEvent } from "@nucleum/client/config/events/clipper-event.type";
import type { ExtensionEvent } from "@nucleum/extensions/extension.type";
import {
  sendToBackground,
  type PlasmoMessaging
} from "@plasmohq/messaging";

type ExtensionRelayMessage = {
  data?: unknown;
  event: ClipperExtensionEvent | ExtensionEvent;
};

type StoredTabPayload = {
  tab?: chrome.tabs.Tab;
};

const sendBackgroundMessage =
  sendToBackground as PlasmoMessaging.SendFx<ClipperExtensionEvent | ExtensionEvent>;

/**
 * @param message
 * @param tabId
 * @returns
 */
export async function relayToContentScript(
  message: ExtensionRelayMessage,
  tabId?: number
): Promise<unknown> {
  if (!tabId) {
    const tabData = (await chrome.storage.local.get("tab")) as StoredTabPayload;
    tabId = tabData?.tab?.id;
  }
  if (typeof tabId !== "number") {
    throw new Error("Unable to resolve content script tab id");
  }
  return new Promise((resolve, reject) => {
    chrome.tabs.sendMessage(tabId, message, (response: unknown) => {
      if (chrome.runtime.lastError) {
        reject(chrome.runtime.lastError);
      } else {
        resolve(response);
      }
    });
  });
}

export async function relayToSidePanel(message: ExtensionRelayMessage) {
  chrome.runtime.sendMessage(message);
}

export async function relayToBackgroundScript(
  message: ExtensionRelayMessage
): Promise<any> {
  try {
    logger.debug({
      at: "relayToBackgroundScript",
      message,
      chromeRuntimeId: chrome.runtime.id
    });

    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(() => {
        reject(
          new Error("Background script communication timeout after 10 seconds")
        );
      }, 10000);
    });

    const backgroundPromise = sendBackgroundMessage<typeof message.data, unknown>({
      name: message.event,
      body: message.data,
      extensionId: chrome.runtime.id
    });

    const response = await Promise.race([backgroundPromise, timeoutPromise]);

    logger.log({
      at: "relayToBackgroundScript - response",
      response
    });
    return response;
  } catch (error) {
    logger.error({
      at: "relayToBackgroundScript - error",
      error
    });
    throw error;
  }
}

export async function openLink(url: string): Promise<chrome.tabs.Tab | undefined> {
  return new Promise((resolve, reject) => {
    chrome.tabs.create({ url: url }, (tab) => {
      if (chrome.runtime.lastError) {
        reject(chrome.runtime.lastError);
      } else {
        resolve(tab);
      }
    });
  });
}

export async function openAppPath(path: string) {
  return openLink(resolveAppPath(path));
}

export function resolveAppPath(path: string) {
  const appUrl =
    (typeof process !== "undefined" ? process.env?.PLASMO_PUBLIC_APP_URL : undefined) ??
    "https://web.memotron.app";
  return appUrl + "/" + path;
}
import {
  ColorStrength,
  type ColorScheme,
  type ColorSchemeSLValues
} from "@21n/theme/appearance.type";

type AppearanceState = {
  colorScheme: ColorScheme;
};

const selectableColorParams: ColorSchemeSLValues[] = [
  {
    saturation: 55,
    lightness: 65,
    colorScheme: "colorscheme:solarizeddark"
  }
];

export function resolveSaturationAndLightness(appearance: AppearanceState) {
  let saturation = 75;
  let lightness = 55;
  if (!appearance || !appearance.colorScheme) return { saturation, lightness };
  let config = selectableColorParams.find(
    (x: ColorSchemeSLValues) => x.colorScheme === appearance.colorScheme.id
  );
  if (config) {
    saturation = config.saturation;
    lightness = config.lightness;
  }
  return { saturation, lightness };
}
export function retrieveCurrentColors(appearance: AppearanceState) {
  let colorScheme = appearance.colorScheme.colors;
  return colorScheme;
}

export function generateCustomColorShade(
  appearance: AppearanceState,
  hue: number,
  shade: number = 1
) {
  let color: string;
  let saturation: number = 50;
  let lightness: number = 50;
  let values = resolveSaturationAndLightness(appearance);
  if (values) {
    saturation = values.saturation;
    lightness = values.lightness;
  }
  if (shade === 1) {
    lightness = appearance.colorScheme.isDark ? 25 : 80;
  } else if (shade === 2) {
    lightness = appearance.colorScheme.isDark ? 20 : 85;
  } else if (shade === 3) {
    lightness = appearance.colorScheme.isDark ? 15 : 92;
  } else if (shade === 4) {
    lightness = appearance.colorScheme.isDark ? 10 : 98;
  }
  color = `hsl(${hue} ${saturation}% ${lightness}% / 1)`;
  return color;
}

/**
 * Generates custom color shades based on theme settings
 * @param appearance
 * @param fallback
 * @param hue
 * @param shade
 * @returns
 */
export function generateCustomColorShades(
  appearance: AppearanceState,
  hue: number
) {
  return [0, 1, 2, 3, 4].map((shade) => {
    return generateCustomColorShade(appearance, hue, shade);
  });
}

/**
 * Use only to access custom color programatically. Use CustomColorPropagator.svelte for rendering custom colors in markup
 * @param appearance
 * @param fallback
 * @param hue
 * @returns
 */
export function customColor(appearance: AppearanceState, hue: number) {
  let color: string;
  let saturation: number = 50;
  let lightness: number = 50;
  let values = resolveSaturationAndLightness(appearance);
  if (values) {
    saturation = values.saturation;
    lightness = values.lightness;
  }
  color = `hsl(${hue} ${saturation}% ${lightness}%)`;
  return color;
}

/**
 * @deprecated - use text-abg class instead if it is accent bg
 * @param appearance
 * @param textColorStrength
 * @param isAccentBgActive
 * @param bgColorHue
 * @returns
 */
export function textColorClass(
  appearance: AppearanceState,
  textColorStrength: ColorStrength = ColorStrength.Normal,
  isAccentBgActive: boolean = false,
  bgColorHue: number | undefined = undefined
) {
  const isActiveFgFg = resolveIfActiveFgFg(bgColorHue, appearance);
  if ((isAccentBgActive && isActiveFgFg) || !isAccentBgActive) {
    switch (textColorStrength) {
      case ColorStrength.ExtraSubtle:
        return "text-fgs3";
      case ColorStrength.Subtle:
        return "text-fgs2";
      case ColorStrength.Normal:
        return "text-fgs1";
      case ColorStrength.Strong:
        return "text-fgs1";
      case ColorStrength.ExtraStrong:
        return "text-fgs1";
      default:
        return "text-fgs2";
    }
  } else {
    switch (textColorStrength) {
      case ColorStrength.ExtraSubtle:
        return "text-bgs3";
      case ColorStrength.Subtle:
        return "text-bgs2";
      case ColorStrength.Normal:
        return "text-bgs1";
      case ColorStrength.Strong:
        return "text-bgs1";
      case ColorStrength.ExtraStrong:
        return "text-bgs1";
      default:
        return "text-bgs2";
    }
  }
}

/**
