 for(const [owner,nodes]of grouped){
  const dest=owner.replace(/\.ts$/,'.test.ts');
  if(require('fs').existsSync(dest))throw Error('Test collision '+dest);
  let body=prefix.map(n=>n.getFullText(sf)).join('\n')+'\n\ndescribe('+JSON.stringify(owner.replace(/\.ts$/,''))+', () => {\n'+[...setup,...nodes].map(n=>n.getFullText(sf)).join('\n')+'\n});\n';
