import { navigation } from "@nucleum/shell/navigation/navigation";
import { get } from "svelte/store";

import { resolveStoredUserInformation } from "@nucleum/client/runtime/account/account-storage";
import account from "@nucleum/client/runtime/account/account.store";
import { ClientStorageKey } from "@nucleum/persistence/persistence.type";
import { clientStorage } from "@nucleum/persistence/persistence.utils";
import { accountSession } from "@nucleum/surfaces/account/account-session";

import {
  UserDataMode,
  UserSessionType
} from "@nucleum/client/runtime/account/account.type";

import { PlanType } from "@nucleum/schema/account/subscription";

import { resolveAuthSession } from "@nucleum/client/runtime/account/auth";
import { logger } from "@nucleum/client/runtime/logging/logger";
/** Hydrates the resolved account session and enforces the supplied product plan requirement. */
export async function performLoginStatusCheck(requiredPlan?: PlanType) {
  const resolution = await resolveAuthSession();
  if (resolution.status === "offline-only") {
    return true;
  }

  if (resolution.status === "cached-cloud") {
    if (
      requiredPlan !== undefined &&
      get(account).plan &&
      get(account).plan.plan !== requiredPlan
    ) {
      navigation.gotoPath("/error/access-denied");
      return false;
    }
    return true;
  }

  if (resolution.status === "expired") {
    logger.warn({
      at: "AuthGuard.performLoginStatusCheck.session.expired",
      currentPath: window.location.pathname
    });
    clearAccountStore();
    navigation.gotoPath("/account/login", {
      queryParams: { msg: "expired" },
      replaceState: true
    });
    return false;
  }

  if (resolution.status === "unavailable") {
    logger.warn({
      at: "AuthGuard.performLoginStatusCheck.session.unavailable",
      error: resolution.error,
      currentPath: window.location.pathname
    });
    navigation.gotoPath("/account/login", {
      queryParams: { msg: "unavailable" },
      replaceState: true
    });
    return false;
  }

  if (resolution.status === "signed-out") {
    clearAccountStore();
    navigation.gotoPath("/account/login", { replaceState: true });
    return false;
  }

  const authSession = resolution.session;
  const subject = authSession.subject ?? {};
  const actorId = String(authSession.actorId ?? "");
  const normalizedActorId = actorId.startsWith("user:")
    ? actorId
    : `user:${actorId}`;
  const unprefixedActorId = normalizedActorId.slice("user:".length);
  const storedUserInfo = resolveStoredUserInformation(
    await clientStorage.get(ClientStorageKey.USER_INFO)
  );
  const currentUserInfo = account.get()?.userInfo ?? storedUserInfo;
  const cachedPlan =
    currentUserInfo?.id === normalizedActorId ? account.get()?.plan : undefined;
  const userInfo = {
    ...currentUserInfo,
    id: normalizedActorId,
    email: authSession.primaryEmail ?? subject.email ?? "",
    isBootstrapped:
      (
        authSession.metadata?.nucleus as
          | { isBootstrapped?: boolean }
          | undefined
      )?.isBootstrapped ?? false,
    nickName:
      currentUserInfo?.nickName ??
      authSession.primaryEmail?.split("@")[0] ??
      subject.email?.split("@")[0] ??
      "App user",
    joinDate: currentUserInfo?.joinDate ?? new Date(),
    lastLogin: new Date(),
    region: authSession.regionId ?? subject.regionId
  };
  await clientStorage.set(ClientStorageKey.USER, authSession);
  await clientStorage.set(ClientStorageKey.USER_INFO, userInfo);
  logger.info({
    at: "AuthGuard.performLoginStatusCheck.session.ok",
    hasAuthFnToken: Boolean(resolution.storedState.authFnToken),
    hasOfflineSession: Boolean(resolution.storedState.offlineSessionId),
    sessionId: authSession.id,
    regionId: authSession.regionId ?? subject.regionId,
    currentPath: window.location.pathname
  });
  account.update((current) => ({
    ...current,
    token: resolution.storedState.authFnToken,
    dataMode: UserDataMode.CLOUD,
    sessionType: UserSessionType.RETURNING,
    userId: unprefixedActorId,
    userInfo: userInfo as any,
    plan: requiredPlan !== undefined ? cachedPlan : current.plan
  }));
  if (requiredPlan !== undefined) {
    const planResolution = await accountSession.refreshPlanData();
    const plan =
      planResolution.status === "resolved" ? planResolution.plan : cachedPlan;
    if (plan?.plan !== requiredPlan) {
      navigation.gotoPath("/error/access-denied");
      return false;
    }
  }
  return true;
}

function clearAccountStore() {
  account.update(() => ({
    dataMode: UserDataMode.NONE,
    sessionType: UserSessionType.UNDETERMINED
  }));
}
import { navigation } from "@nucleum/shell/navigation/navigation";

import { ClientStorageKey } from "@nucleum/persistence/persistence.type";
import { clientStorage } from "@nucleum/persistence/persistence.utils";

import { postTokenToExtension } from "@nucleum/client/runtime/embed/embed.utils";

import { shouldUseAuthFnBearerSession } from "@nucleum/client/runtime/account/auth";

/** Completes the pending browser-extension login handoff after session validation. */
export async function completeExtensionLogin(): Promise<boolean> {
  const isLoginFromExtension = await clientStorage.getForSession(
    ClientStorageKey.IS_EXTENSION_LOGIN
  );
  if (isLoginFromExtension) {
    clientStorage.removeForSession(ClientStorageKey.IS_EXTENSION_LOGIN);
    const userInfo = await clientStorage.get(ClientStorageKey.USER_INFO);
    const token = shouldUseAuthFnBearerSession()
      ? await clientStorage.get(ClientStorageKey.AUTHFN_TOKEN)
      : undefined;
    postTokenToExtension({ token, userInfo });
    navigation.gotoPath("/ext/login");
    return true;
  }

  return false;
}
<script lang="ts">
  import { elementPlatform as context } from "@21n/ui/environment/element-environment.store";
  import { getElementActionHost } from "@21n/ui/hosts/action-host";
  import { LinkVariant } from "@21n/ui/elements/button/button.type";
  import { cn } from "@21n/ui/environment/presentation";
  import { isValidEmail } from "@21n/shared-utils/text.utils";
  import { isUrlMatchPattern } from "@21n/shared-utils/utils";

  let {
    href = undefined,
    label,
    variant = LinkVariant.DOTTED,
    isEnforeHttpIfMatchPattern = false,
    onclick = undefined
  }: {
    href?: string | undefined;
    label: string;
    variant?: LinkVariant;
    isEnforeHttpIfMatchPattern?: boolean;
    onclick?: ((event: MouseEvent) => void) | undefined;
  } = $props();

  function handleClick(event: MouseEvent) {
    if (!href) return;
    const host = getElementActionHost();
    const url = href.includes("http")
      ? href
      : isEnforeHttpIfMatchPattern && isUrlMatchPattern(href)
        ? `https://${href}`
        : undefined;
    if (url) {
      if (host) host.openLink(url);
      else window.open(url, "_blank", "noopener,noreferrer");
    } else if (isValidEmail(href)) host?.navigate?.(`mailto:${href}`);
    else host?.runAction(href);
    onclick?.(event);
  }
</script>

{#if href && !$context.isEmbed && href?.includes("http")}
  <a
    class={cn("relative hover:text-aps1 whitespace-nowrap min-w-fit", {
      "underline-dotted hover:underline-dotted-hover":
        variant === LinkVariant.DOTTED
    })}
    {href}
    target="_blank"
    rel="noopener noreferrer"
    >{label}
  </a>
{:else}
  <button
    onclick={handleClick}
    class={cn("hover:text-aps1 whitespace-nowrap min-w-fit", {
      "underline-dotted hover:underline-dotted-hover":
        variant === LinkVariant.DOTTED
    })}
  >
    {label}
  </button>
{/if}
import { navigation } from "@nucleum/shell/navigation/navigation";
import { get } from "svelte/store";

import { goto } from "$app/navigation";

import { GlobalEvent } from "@nucleum/shared-state/events/event.enum";

import context from "@nucleum/client/runtime/context.store";

import { logger } from "@nucleum/client/runtime/logging/logger";

function handleCustomNavigation(event: any) {
  logger.log({
    at: "handleCustomNavigation",
    event,
    path: event.detail?.path
  });
  logger.info({
    at: "BaseLayer.handleCustomNavigation",
    path: event.detail?.path,
    isReload: event.detail?.isReload,
    replaceState: event.detail?.replaceState,
    currentPath: window.location.pathname,
    protocol: window.location.protocol,
    isEmbed: get(context).isEmbed
  });
  if (event.detail?.isReload) {
    if (!get(context).isEmbed) window.location.reload();
    else {
      goto(
        (import.meta.env?.VITE_CUSTOM_PROTOCOL ?? "tauri") +
          "://localhost/index.html"
      );
    }
  }
  const host = window.location.host;
  if (
    event.detail.path &&
    ((event.detail.path.includes("http") &&
      event.detail.path.includes(host) &&
      !event.detail.path.includes("/oauth/")) ||
      !event.detail.path.includes("http")) &&
    !event.detail.path.includes("mailto:") &&
    !event.detail.path.includes("//oauthsignin")
  ) {
    goto(event.detail.path, {
      replaceState: event.detail?.replaceState ?? false
    });
  } else if (event.detail.path) window.location = event.detail.path;
}

function handleToggleSearchParam(event: any) {
  navigation.toggleSearchParam(event.detail);
}

function handlePlaceholderClick(event: Event) {
  const target = event.target as HTMLElement | null;
  if (target?.tagName === "PLACEHOLDER" && target.dataset?.href) {
    navigation.openLink(target.dataset.href);
  }
}
/** Installs browser navigation event handlers and returns their disposer. */
export function installBrowserNavigation() {
  window.addEventListener(
    GlobalEvent.CUSTOM_NAVIGATION,
    handleCustomNavigation
  );
  window.addEventListener(
    GlobalEvent.TOGGLE_SEARCH_PARAM,
    handleToggleSearchParam
  );
  window.addEventListener("click", handlePlaceholderClick);
  const handlePopState = () =>
    navigation.setCurrentPath(document.location.pathname);
  window.addEventListener("popstate", handlePopState);
  return () => {
    window.removeEventListener(
      GlobalEvent.CUSTOM_NAVIGATION,
      handleCustomNavigation
    );
    window.removeEventListener(
      GlobalEvent.TOGGLE_SEARCH_PARAM,
      handleToggleSearchParam
    );
    window.removeEventListener("click", handlePlaceholderClick);
    window.removeEventListener("popstate", handlePopState);
  };
}
import { type DatafnStorageAdapter } from "@datafn/client";
import { deleteIndexedDbDatabase } from "@nucleum/persistence/persistence.utils";

/** Closes a runtime storage adapter when one is installed. */
export async function closeNucleumDatafnRuntimeStorage(
  storage: DatafnStorageAdapter | undefined
) {
  if (!storage) return;
  await storage.close();
}

/** Deletes the selected local data and search databases. */
export async function deleteDatafnLocalClone(storageDbName: string) {
  await Promise.all([
    deleteIndexedDbDatabase(storageDbName),
    deleteIndexedDbDatabase(`${storageDbName}-search`)
  ]);
}

