    sessionTotals.focus + sessionTotals.brek - totalTimeFromLogs;
  if (remainingTime > 0) {
    logs.push({
      id: generateResourceId(Resource.sessionLog),
      startUnix: session.startUnix,
      endUnix: session.endUnix,
      sessionId: session.id,
      focus: remainingTime,
      breakTime: 0
    });
