      response.end(body);
    } catch {
      response.writeHead(500);
      response.end("Internal server error");
    }
  });

  return {
    listen(port) {
      return new Promise((resolve, reject) => {
        server.once("error", reject);
        server.listen(port, "127.0.0.1", () => {
          server.off("error", reject);
