  const baseURL = getProjectBaseURL(projectName);
  const authPath = getAuthFilePath(projectName);
  const use = {
    ...devices["Desktop Chrome"],
    viewport: defaultViewport,
    video: "on" as const,
    trace: "on-first-retry" as const,
    screenshot: "only-on-failure" as const,
