const fs=require('fs'); const dir='/tmp/nucleus-playwright.N9JTkc';
function entries(name){ const report=JSON.parse(fs.readFileSync(`${dir}/${name}.json`)); const out=[];function walk(s){for(const sp of s.specs||[])for(const t of sp.tests||[])out.push({id:sp.id,project:t.projectName,file:sp.file,line:sp.line,title:sp.title,status:t.status,expected:t.expectedStatus,results:t.results,annotations:t.annotations});for(const x of s.suites||[])walk(x)}report.suites.forEach(walk);return out;}
const n=entries('nucleum'),p=entries('pointron'),m=entries('memotron'),r=entries('memotron-settings-smoke');const by=new Map(m.map(x=>[x.id,x]));for(const x of r){if(!by.has(x.id))throw Error('Unknown rerun id '+x.id);by.set(x.id,x)}const all=[...n,...p,...by.values()]; const stats={}; for(const t of all){const s=stats[t.project]??={};s[t.status]=(s[t.status]||0)+1;}console.log(JSON.stringify({stats,total:all.length,unfinished:all.filter(x=>!x.results.length||x.results.some(y=>y.status==='interrupted')).map(x=>[x.file,x.title,x.status]),skips:all.filter(x=>x.status==='skipped').map(x=>({project:x.project,title:x.title,reasons:x.annotations}))},null,2));
NODE","max_output_tokens":3000}));

