const fs=require('fs'),d='/tmp/nucleus-playwright.N9JTkc';let all=[];for(const n of ['nucleum','pointron','memotron','memotron-settings-smoke']){let a=[];function w(s){for(const p of s.specs||[])for(const t of p.tests||[])a.push({file:p.file,line:p.line,title:p.title,id:p.id,...t});for(const c of s.suites||[])w(c)}w(JSON.parse(fs.readFileSync(d+'/'+n+'.json')));if(n==='memotron-settings-smoke'){const ids=new Set(a.map(x=>x.id));all=all.filter(x=>!ids.has(x.id));}all.push(...a);}const groups=new Map();for(const t of all.filter(x=>x.status==='unexpected')){const e=t.results.at(-1);const msg=(e.errors||[]).map(x=>x.message||'').join('\n').replace(/\x1b\[[0-9;]*[A-Za-z]/g,'');const k=t.file+':'+t.line;const o=groups.get(k)||{file:t.file,line:t.line,title:t.title,cases:[]};o.cases.push({p:t.projectName,error:msg.slice(0,1800),stack:(e.errors||[]).map(x=>x.stack?.split('\n').filter(l=>l.includes(' at ')).slice(-3))});groups.set(k,o);}console.log(JSON.stringify([...groups.values()],null,2));
