async function installPipMock(
  page: Page,
  options: { rejectWith?: string } = {}
) {
  await page.evaluate(({ rejectWith }) => {
    const listeners = new Set<(event: Event) => void>();
    const api: any = {
      requestCount: 0,
      window: null
    };
    const pipWindow: any = {
      document,
