              notes: session.notes,
              plannedEndUnix: session.plannedEndUnix
                ? Number(session.plannedEndUnix)
                : undefined,
              startUnix: Number(session.startUnix ?? 0),
              type: session.type
            }
          : undefined
      };
    },
    { modulePath: datafnStorePath, sessionId }
  );
}

