export async function reloadActiveSession(page: Page) {
  await page.reload({ waitUntil: "domcontentloaded" });
  await ensureInAppOnHome(page);
  await expect(
    page.getByRole("button", { name: /^\d{2}:\d{2}(?::\d{2})?$/ }).last()
  ).toBeVisible({ timeout: 15_000 });
}
